import{_ as e,o,c as a,ae as r}from"./chunks/framework.RRduUuAx.js";const u=JSON.parse('{"title":"iCost Bill Import Guide","description":"","frontmatter":{},"headers":[],"relativePath":"v1/en/guide/08-icost-bill-import-guide.md","filePath":"v1/en/guide/08-icost-bill-import-guide.md"}'),i={name:"v1/en/guide/08-icost-bill-import-guide.md"};function l(d,t,s,n,p,h){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="icost-bill-import-guide" tabindex="-1">iCost Bill Import Guide <a class="header-anchor" href="#icost-bill-import-guide" aria-label="Permalink to &quot;iCost Bill Import Guide&quot;">​</a></h1><h2 id="📋-overview" tabindex="-1">📋 Overview <a class="header-anchor" href="#📋-overview" aria-label="Permalink to &quot;📋 Overview&quot;">​</a></h2><p>This guide shows how to export bills from <strong>iCost</strong> and import them into <strong>Koala</strong>.</p><p>Koala supports <strong>iCost Excel export</strong> (<code>.xlsx</code> or <code>.xls</code>). CSV exported from iCost is not supported.</p><hr><h2 id="📱-part-1-export-in-icost" tabindex="-1">📱 Part 1: Export in iCost <a class="header-anchor" href="#📱-part-1-export-in-icost" aria-label="Permalink to &quot;📱 Part 1: Export in iCost&quot;">​</a></h2><p>Menu names may differ across versions:</p><ol><li>Open iCost</li><li>Go to <strong>Settings / More</strong></li><li>Find <strong>Export / Data export / Export bills</strong></li><li>Choose <strong>Excel (.xlsx / .xls)</strong></li><li>Choose a date range (recommended up to 3 months)</li><li>Export and save the file</li></ol><blockquote><p>⚠️ Important: If you export as CSV, Koala will show a message that CSV is not supported.</p></blockquote><hr><h2 id="📱-part-2-import-into-koala" tabindex="-1">📱 Part 2: Import into Koala <a class="header-anchor" href="#📱-part-2-import-into-koala" aria-label="Permalink to &quot;📱 Part 2: Import into Koala&quot;">​</a></h2><ol><li>Open Koala and go to <strong>Settings</strong> then <strong>Bill Import</strong></li><li>Set <strong>Import source</strong> to <strong>iCost</strong></li><li>Choose the exported Excel file</li><li>Link the target ledger</li><li>Tap <strong>Parse</strong> then preview and tap <strong>Import</strong></li></ol><hr><h2 id="📋-icost-excel-format-how-koala-reads-it" tabindex="-1">📋 iCost Excel format (how Koala reads it) <a class="header-anchor" href="#📋-icost-excel-format-how-koala-reads-it" aria-label="Permalink to &quot;📋 iCost Excel format (how Koala reads it)&quot;">​</a></h2><p>Koala checks:</p><ul><li>The Excel file has a readable worksheet</li><li>The header row contains <strong>&quot;日期&quot;</strong> (used to locate the header)</li></ul><p>Tip: If iCost lets you choose export language, export with Chinese headers (at least keep &quot;日期&quot;).</p><h3 id="columns-by-position" tabindex="-1">Columns (by position) <a class="header-anchor" href="#columns-by-position" aria-label="Permalink to &quot;Columns (by position)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Field</th><th>Notes</th></tr></thead><tbody><tr><td>1</td><td>Date</td><td>Date strings (multiple formats) or Excel serial date</td></tr><tr><td>2</td><td>Type</td><td>Must contain the keyword for expense or income</td></tr><tr><td>3</td><td>Amount</td><td><code>+</code> or <code>-</code> allowed; thousands separators are handled</td></tr><tr><td>4</td><td>Parent category</td><td>Used to match Koala categories</td></tr><tr><td>5</td><td>Child category</td><td>If empty, Koala uses parent category</td></tr><tr><td>6</td><td>Account</td><td>If empty, Koala uses a default account</td></tr><tr><td>8</td><td>Note</td><td>Text</td></tr><tr><td>9</td><td>Currency code</td><td>For example <code>CNY</code> or <code>USD</code> (fallback to ledger default)</td></tr><tr><td>10</td><td>Tags</td><td>Comma-separated (<code>,</code> or <code>，</code>)</td></tr></tbody></table><hr><h2 id="📚-related-guides" tabindex="-1">📚 Related Guides <a class="header-anchor" href="#📚-related-guides" aria-label="Permalink to &quot;📚 Related Guides&quot;">​</a></h2><ul><li><a href="./01-template-bill-import-guide">Template Bill Import (CSV)</a></li><li><a href="./02-wechat-bill-import-guide">WeChat Bill Import</a></li><li><a href="./03-alipay-bill-import-guide">Alipay Bill Import</a></li><li><a href="./07-pixiu-bill-import-guide">Pixiu Bill Import</a></li><li><a href="./04-multi-ledger-guide">Multi-ledger</a></li></ul><hr><p><strong>Last updated</strong>: Apr 2026</p>',24)])])}const m=e(i,[["render",l]]);export{u as __pageData,m as default};
